#include <iostream>
#include <string>
#include <utility>

// Component class demonstrating a HAS-A relationship
class Engine {
public:
    explicit Engine(int horsepower) : horsepower_{horsepower} {}
    int getHorsepower() const { return horsepower_; }
private:
    int horsepower_{0};
};

// Base class representing a general vehicle
class Vehicle {
public:
    explicit Vehicle(std::string model)
        : model_{std::move(model)} {}

    const std::string& getModel() const { return model_; }

private:
    std::string model_;
};

// Derived class: Car IS-A Vehicle, and Car HAS-A Engine
class Car : public Vehicle {
public:
    Car(std::string model, int horsepower)
        : Vehicle(std::move(model)), engine_{horsepower} {}

    void displayInfo() const {
        std::cout << "Model: " << getModel() << "\n"
                  << "Engine: " << engine_.getHorsepower() << " HP\n";
    }

private:
    Engine engine_; // HAS-A: Car contains an Engine
};

int main() {
    Car sedan{"Alpha-200", 180};
    sedan.displayInfo();
    return 0;
}

body.vi:
Để khai báo một lớp dẫn xuất kế thừa từ một lớp cơ sở, ta dùng cú pháp dấu hai chấm `:` theo sau bởi quyền kế thừa (thường là `public`) và tên lớp cơ sở:
```cpp
class TwoDimensionalShape : public Shape {
    // Nội dung lớp dẫn xuất
};
```

**Cơ chế đóng gói dữ liệu quan trọng:**
- Dù kế thừa theo hình thức nào, các thành viên mang phạm vi `private` của lớp cơ sở **không bao giờ có thể truy cập trực tiếp** từ bên trong mã nguồn của lớp dẫn xuất.
- Các thành viên `private` này vẫn tồn tại trong không gian bộ nhớ của đối tượng dẫn xuất (vẫn được kế thừa về mặt vật lý), nhưng lớp dẫn xuất bắt buộc phải tương tác với chúng gián tiếp qua các hàm thành viên `public` hoặc `protected` do lớp cơ sở cung cấp (ví dụ qua các hàm getter/setter).
- Với **kế thừa công khai (public inheritance)**, các thành viên `public` của lớp cơ sở giữ nguyên phạm vi `public` tại lớp dẫn xuất, đảm bảo các hàm gọi bên ngoài có thể tương tác bình thường.

body.en:
To declare a derived class in C++, specify a colon `:` followed by the inheritance access specifier (predominantly `public`) and the base class name:
```cpp
class TwoDimensionalShape : public Shape {
    // Specialized members and overrides
};
```

**Crucial Encapsulation Rules:**
- Regardless of the inheritance specifier, `private` members of the base class are **never directly accessible** within the member functions of the derived class.
- Base-class private data members are physically present within the derived-class object's memory layout, but the derived class must manipulate them through inherited `public` or `protected` interface methods (such as public getters and setters).
- Under **public inheritance**, public members of the base class retain their `public` access status in the derived class, preserving client-facing interfaces.

example.code:
#include <iostream>
#include <string>
#include <utility>

// Top-level indirect base class
class CommunityMember {
public:
    explicit CommunityMember(std::string name) : name_{std::move(name)} {}

    // Public accessor allowing derived classes to read private data
    const std::string& getName() const { return name_; }

private:
    std::string name_; // Inaccessible directly in derived classes
};

// Direct base class to Faculty, derived from CommunityMember
class Employee : public CommunityMember {
public:
    Employee(std::string name, std::string department)
        : CommunityMember{std::move(name)}, department_{std::move(department)} {}

    const std::string& getDepartment() const { return department_; }

private:
    std::string department_;
};

// Derived class at the bottom of this branch (Single Inheritance)
class Faculty : public Employee {
public:
    Faculty(std::string name, std::string department, std::string rank)
        : Employee{std::move(name), std::move(department)}, rank_{std::move(rank)} {}

    void printProfile() const {
        // Accessing inherited properties via base-class public member functions
        std::cout << "Member: " << getName() << "\n"
                  << "Department: " << getDepartment() << "\n"
                  << "Academic Rank: " << rank_ << "\n";
    }

private:
    std::string rank_;
};

int main() {
    Faculty professor{"Dr. Ada Lovelace", "Computer Science", "Distinguished Professor"};
    professor.printProfile();
    return 0;
}
